166	/// Card types.
167	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
168	pub enum CardType {
169	    Land,
170	    Creature,
171	    Instant,
172	    Sorcery,
173	    Enchantment,
174	    Artifact,
175	    Planeswalker,
176	}
