276	/// Counter types that can exist on permanents.
277	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
278	pub enum CounterType {
279	    PlusOnePlusOne,
280	    MinusOneMinusOne,
281	    Loyalty,
282	    Slime,
283	    Study,
284	    // extend as needed
285	}
