287	/// Keyword abilities.
288	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
289	pub enum Keyword {
290	    Flying,
291	    FirstStrike,
292	    DoubleStrike,
293	    Trample,
294	    Deathtouch,
295	    Lifelink,
296	    Vigilance,
297	    Flash,
298	    Reach,
